const fs = require('fs');
const path = require('path');

const recipes = [];

function add(id, name, desc, cuisine, mealType, dietType, diff, prep, cook, servings, cost, img, tags, steps, nut, ings) {
  recipes.push({
    id: `cat-${id}`,
    name,
    description: desc,
    cuisine,
    meal_type: mealType,
    diet_type: dietType,
    difficulty: diff,
    preparation_time: prep,
    cooking_time: cook,
    total_time: prep + cook,
    servings,
    estimated_cost: cost,
    image_url: img,
    tags,
    instructions: steps.map((s, idx) => ({ step: idx + 1, instruction: s.text, timerMinutes: s.time })),
    nutrition: nut,
    ingredients: ings.map(i => ({ name: i.name, quantity: i.qty, unit: i.unit, category: i.cat || 'Pantry' }))
  });
}

// 1. EGG DISHES
add('001', 'French Butter Rolled Omelette', 'Classic Parisian soft and velvety folded omelette with fresh herbs, chives, and creamy butter.', 'Continental', 'Breakfast', 'Eggetarian', 'Medium', 5, 5, 2, 80, 'https://images.unsplash.com/photo-1510693206972-df098062cb71?auto=format&fit=crop&w=600&q=80', ['Breakfast', 'Eggs', 'High Protein', 'Quick 10m'], [{ text: 'Crack 3 eggs into a bowl with a pinch of salt and black pepper; whisk vigorously until completely homogeneous.', time: 2 }, { text: 'Melt generous butter in an 8-inch non-stick skillet over medium-low heat until foaming.', time: 2 }, { text: 'Pour in eggs and shake pan while stirring rapidly in small circles with a spatula until soft curds form.', time: 2 }, { text: 'Tilt skillet, gently roll into an almond cylinder shape, and slide onto a warm plate with fresh chives.', time: 1 }], { calories: 260, protein: 18, carbs: 2, fat: 20, fiber: 0 }, [{ name: 'Egg', qty: 3, unit: 'pcs', cat: 'Proteins' }, { name: 'Butter', qty: 2, unit: 'tbsp', cat: 'Dairy' }, { name: 'Black Pepper', qty: 0.5, unit: 'tsp', cat: 'Spices' }, { name: 'Coriander', qty: 1, unit: 'tbsp', cat: 'Vegetables' }]);

add('002', 'Classic Soft Scrambled Eggs with Buttered Toast', 'Luxurious creamy scrambled eggs cooked slowly over gentle heat, served atop crisp golden toasted bread.', 'Continental', 'Breakfast', 'Eggetarian', 'Easy', 5, 7, 2, 90, 'https://images.unsplash.com/photo-1525351484163-7529414344d8?auto=format&fit=crop&w=600&q=80', ['Breakfast', 'Eggs', 'Comfort Food', '10m Meal'], [{ text: 'Whisk eggs with a splash of milk, salt, and freshly cracked black pepper.', time: 2 }, { text: 'Melt butter in a skillet over low heat and pour in egg mixture.', time: 2 }, { text: 'Gently sweep spatula across the pan creating soft, creamy folds. Remove just before set.', time: 3 }, { text: 'Toast bread slices until golden brown; butter generously and spoon hot scrambled eggs on top.', time: 2 }], { calories: 340, protein: 20, carbs: 26, fat: 18, fiber: 2 }, [{ name: 'Egg', qty: 4, unit: 'pcs', cat: 'Proteins' }, { name: 'Bread', qty: 2, unit: 'slices', cat: 'Grains' }, { name: 'Butter', qty: 2, unit: 'tbsp', cat: 'Dairy' }, { name: 'Milk', qty: 3, unit: 'tbsp', cat: 'Dairy' }]);

add('003', 'Street Style Mumbai Egg Bhurji', 'Fiery scrambled eggs tossed with finely chopped onions, juicy tomatoes, slit green chillies, and aromatic cumin.', 'Indian', 'Dinner', 'Eggetarian', 'Easy', 8, 10, 2, 70, 'https://images.unsplash.com/photo-1589301760014-d929f3979dbc?auto=format&fit=crop&w=600&q=80', ['Street Food', 'Quick', 'Spicy', 'Eggs'], [{ text: 'Heat oil or butter in a pan; add cumin seeds and sauté chopped onions, ginger, and green chillies until translucent.', time: 3 }, { text: 'Add chopped tomatoes, turmeric, red chilli powder, and salt. Cook until tomatoes turn mushy.', time: 3 }, { text: 'Crack eggs directly into the masala or whisk beforehand. Scramble vigorously over medium-high heat until cooked.', time: 4 }, { text: 'Finish with chopped fresh coriander and squeeze fresh lemon juice. Serve hot with pav or roti.', time: 1 }], { calories: 280, protein: 19, carbs: 9, fat: 19, fiber: 2 }, [{ name: 'Egg', qty: 3, unit: 'pcs', cat: 'Proteins' }, { name: 'Onion', qty: 1, unit: 'pcs', cat: 'Vegetables' }, { name: 'Tomato', qty: 2, unit: 'pcs', cat: 'Vegetables' }, { name: 'Green Chilli', qty: 2, unit: 'pcs', cat: 'Vegetables' }, { name: 'Coriander', qty: 2, unit: 'tbsp', cat: 'Vegetables' }, { name: 'Butter', qty: 1, unit: 'tbsp', cat: 'Dairy' }]);

add('004', 'Cheesy Egg-in-a-Hole (Toad in the Hole)', 'Fun and crispy breakfast bread with a sunny egg cooked directly inside the center cutout, topped with melted cheese.', 'American', 'Breakfast', 'Eggetarian', 'Easy', 3, 6, 1, 65, 'https://images.unsplash.com/photo-1525351484163-7529414344d8?auto=format&fit=crop&w=600&q=80', ['Breakfast', 'Kids Favorite', 'Quick', 'Cheese'], [{ text: 'Cut a 2-inch circle from the center of bread slice using a biscuit cutter or glass rim.', time: 1 }, { text: 'Melt butter in a pan over medium heat; place bread slice and the cutout circle into the pan.', time: 1 }, { text: 'Crack egg directly into the center hole. Season with salt, pepper, and top with cheese.', time: 3 }, { text: 'Flip gently once the bottom is golden and egg white is partially set. Cook for 2 more minutes.', time: 2 }], { calories: 310, protein: 16, carbs: 22, fat: 18, fiber: 1.5 }, [{ name: 'Egg', qty: 1, unit: 'pcs', cat: 'Proteins' }, { name: 'Bread', qty: 1, unit: 'slices', cat: 'Grains' }, { name: 'Butter', qty: 1, unit: 'tbsp', cat: 'Dairy' }, { name: 'Cheese', qty: 30, unit: 'g', cat: 'Dairy' }]);

add('005', 'Classic Golden French Toast with Honey & Cinnamon', 'Thick slices of bread dipped in a rich spiced egg-milk batter and pan-fried golden brown with honey.', 'Continental', 'Breakfast', 'Eggetarian', 'Easy', 5, 8, 2, 85, 'https://images.unsplash.com/photo-1484723091739-00821c432021?auto=format&fit=crop&w=600&q=80', ['Breakfast', 'Sweet', 'Brunch', 'Comfort'], [{ text: 'Whisk eggs, milk, cinnamon powder, and a teaspoon of honey or sugar in a wide shallow bowl.', time: 2 }, { text: 'Heat butter in a non-stick skillet over medium flame.', time: 1 }, { text: 'Dip bread slices in the egg mixture for 15 seconds per side until soaked but not soggy.', time: 1 }, { text: 'Cook slices in the pan for 3 minutes per side until golden brown and puffed. Drizzle honey and serve warm.', time: 4 }], { calories: 360, protein: 14, carbs: 46, fat: 14, fiber: 2 }, [{ name: 'Bread', qty: 4, unit: 'slices', cat: 'Grains' }, { name: 'Egg', qty: 2, unit: 'pcs', cat: 'Proteins' }, { name: 'Milk', qty: 0.5, unit: 'cup', cat: 'Dairy' }, { name: 'Honey', qty: 2, unit: 'tbsp', cat: 'Pantry' }, { name: 'Butter', qty: 1.5, unit: 'tbsp', cat: 'Dairy' }]);

add('006', 'Dhaba Style Egg Curry', 'Boiled eggs lightly fried with turmeric and simmered in a spiced onion, tomato, ginger-garlic gravy.', 'Indian', 'Dinner', 'Eggetarian', 'Easy', 10, 20, 3, 110, 'https://images.unsplash.com/photo-1546833999-b9f581a1996d?auto=format&fit=crop&w=600&q=80', ['Curry', 'Egg', 'Dhaba Style', 'Gluten-Free'], [{ text: 'Boil eggs for 10 minutes, peel, make shallow slits, and pan-fry in oil with a pinch of turmeric until golden.', time: 5 }, { text: 'In same pan, sauté cumin seeds, chopped onions, and ginger-garlic paste until deeply browned.', time: 5 }, { text: 'Stir in tomato puree, red chilli powder, coriander powder, garam masala, and salt; cook until oil releases.', time: 5 }, { text: 'Pour 1 cup water, drop in fried eggs, simmer for 5 minutes, and garnish with fresh coriander.', time: 5 }], { calories: 290, protein: 18, carbs: 12, fat: 19, fiber: 3 }, [{ name: 'Egg', qty: 4, unit: 'pcs', cat: 'Proteins' }, { name: 'Onion', qty: 2, unit: 'pcs', cat: 'Vegetables' }, { name: 'Tomato', qty: 2, unit: 'pcs', cat: 'Vegetables' }, { name: 'Garlic', qty: 6, unit: 'cloves', cat: 'Vegetables' }, { name: 'Ginger', qty: 1, unit: 'inch', cat: 'Vegetables' }, { name: 'Coriander', qty: 2, unit: 'tbsp', cat: 'Vegetables' }]);

add('007', 'Creamy Egg Salad Sandwich', 'Hard-boiled eggs diced and mixed with creamy mayo or hung curd, mustard, black pepper, and crisp celery on toast.', 'American', 'Lunch', 'Eggetarian', 'Easy', 10, 5, 2, 95, 'https://images.unsplash.com/photo-1528735602780-2552fd46c7af?auto=format&fit=crop&w=600&q=80', ['Sandwich', 'Quick', 'No Cook', 'High Protein'], [{ text: 'Roughly chop hard-boiled eggs into small uniform cubes.', time: 2 }, { text: 'In a bowl, mix eggs with mayonnaise or yogurt, mustard, black pepper, and chopped onions.', time: 2 }, { text: 'Toast bread slices lightly until crisp.', time: 2 }, { text: 'Spread generous egg salad filling between bread slices, slice diagonally, and enjoy.', time: 1 }], { calories: 380, protein: 21, carbs: 28, fat: 20, fiber: 2 }, [{ name: 'Egg', qty: 4, unit: 'pcs', cat: 'Proteins' }, { name: 'Bread', qty: 4, unit: 'slices', cat: 'Grains' }, { name: 'Onion', qty: 1, unit: 'pcs', cat: 'Vegetables' }, { name: 'Black Pepper', qty: 0.5, unit: 'tsp', cat: 'Spices' }, { name: 'Butter', qty: 1, unit: 'tbsp', cat: 'Dairy' }]);

add('008', 'Spicy Boiled Egg Pepper Fry', 'Hard boiled egg halves tossed on a tawa with caramelized onions, curry leaves, crushed garlic, and black pepper.', 'South Indian', 'Dinner', 'Eggetarian', 'Easy', 5, 10, 2, 75, 'https://images.unsplash.com/photo-1546833999-b9f581a1996d?auto=format&fit=crop&w=600&q=80', ['South Indian', 'Quick', 'High Protein', 'Appetizer'], [{ text: 'Cut hard boiled eggs lengthwise into halves.', time: 1 }, { text: 'Heat oil in a flat pan; splutter mustard seeds, curry leaves, and lots of sliced onions and garlic.', time: 3 }, { text: 'Add turmeric, red chilli powder, and lots of freshly crushed black pepper with salt.', time: 2 }, { text: 'Place egg halves face down, spoon the spicy onion-pepper masala on top, and roast for 4 minutes until crisp.', time: 4 }], { calories: 230, protein: 17, carbs: 8, fat: 15, fiber: 1.8 }, [{ name: 'Egg', qty: 4, unit: 'pcs', cat: 'Proteins' }, { name: 'Onion', qty: 2, unit: 'pcs', cat: 'Vegetables' }, { name: 'Curry Leaves', qty: 1, unit: 'sprig', cat: 'Vegetables' }, { name: 'Black Pepper', qty: 1.5, unit: 'tsp', cat: 'Spices' }, { name: 'Garlic', qty: 5, unit: 'cloves', cat: 'Vegetables' }]);

add('009', 'Fiery Egg Fried Rice', 'Cold cooked basmati rice wok-tossed with fluffy scrambled eggs, garlic, spring onions, and spicy soy seasoning.', 'Asian', 'Dinner', 'Eggetarian', 'Easy', 5, 8, 2, 85, 'https://images.unsplash.com/photo-1603133872878-684f208fb84b?auto=format&fit=crop&w=600&q=80', ['Fried Rice', 'Asian', 'Quick 15m', 'Eggs'], [{ text: 'Beat 2 eggs with a pinch of salt. Scramble in a smoking hot wok with 1 tsp oil until just set; set aside.', time: 2 }, { text: 'Add remaining oil; stir-fry minced garlic, onions, and green chillies for 1 minute.', time: 1 }, { text: 'Add chilled cooked rice and toss vigorously on high heat for 2 minutes.', time: 2 }, { text: 'Fold in scrambled eggs, 1 tbsp soy sauce, and black pepper. Toss on blazing flame for 2 minutes and garnish with spring onions.', time: 2 }], { calories: 390, protein: 15, carbs: 58, fat: 11, fiber: 2 }, [{ name: 'Rice', qty: 2, unit: 'cups', cat: 'Grains' }, { name: 'Egg', qty: 3, unit: 'pcs', cat: 'Proteins' }, { name: 'Garlic', qty: 4, unit: 'cloves', cat: 'Vegetables' }, { name: 'Onion', qty: 1, unit: 'pcs', cat: 'Vegetables' }, { name: 'Green Chilli', qty: 2, unit: 'pcs', cat: 'Vegetables' }]);

add('010', 'Mediterranean Shakshuka with Poached Eggs', 'Silky spiced stew of simmering tomatoes, sweet bell peppers, onions, and cumin with soft eggs poached right in the sauce.', 'Mediterranean', 'Breakfast', 'Eggetarian', 'Easy', 8, 15, 2, 110, 'https://images.unsplash.com/photo-1590412200988-a436970781fa?auto=format&fit=crop&w=600&q=80', ['Shakshuka', 'Breakfast', 'One Pan', 'Healthy'], [{ text: 'Heat olive oil in a skillet; sauté chopped onions, minced garlic, and diced bell peppers for 5 minutes until soft.', time: 5 }, { text: 'Add chopped tomatoes, cumin, paprika, salt, and black pepper. Simmer for 8 minutes until a thick rich sauce forms.', time: 8 }, { text: 'Make 3 small wells in the sauce with a spoon; crack an egg directly into each well.', time: 2 }, { text: 'Cover skillet with a lid and cook on low heat for 5 minutes until egg whites are set but yolks remain runny. Garnish with coriander.', time: 5 }], { calories: 290, protein: 17, carbs: 16, fat: 18, fiber: 4 }, [{ name: 'Egg', qty: 3, unit: 'pcs', cat: 'Proteins' }, { name: 'Tomato', qty: 4, unit: 'pcs', cat: 'Vegetables' }, { name: 'Bell Pepper', qty: 1, unit: 'pcs', cat: 'Vegetables' }, { name: 'Onion', qty: 1, unit: 'pcs', cat: 'Vegetables' }, { name: 'Garlic', qty: 4, unit: 'cloves', cat: 'Vegetables' }, { name: 'Coriander', qty: 2, unit: 'tbsp', cat: 'Vegetables' }]);

