add('011', 'Pan-Seared Garlic Lemon Butter Chicken', 'Succulent tender chicken breasts seared in a skillet with sizzling garlic, fresh lemon juice, butter, and cracked pepper.', 'Continental', 'Dinner', 'Non-Vegetarian', 'Easy', 10, 15, 2, 190, 'https://images.unsplash.com/photo-1604908176997-125f25cc6f3d?auto=format&fit=crop&w=600&q=80', ['Chicken', 'Keto', 'High Protein', '20m Meal'], [{ text: 'Pound chicken breasts to even thickness; season both sides with salt, black pepper, and garlic powder.', time: 3 }, { text: 'Heat 1 tbsp olive oil and 1 tbsp butter in a skillet over medium-high heat.', time: 2 }, { text: 'Sear chicken for 5-6 minutes per side until golden brown and cooked through (165°F internally).', time: 7 }, { text: 'Add minced garlic, remaining butter, and fresh lemon juice; baste chicken with the bubbling sauce for 2 minutes.', time: 2 }], { calories: 380, protein: 42, carbs: 3, fat: 22, fiber: 0.5 }, [{ name: 'Chicken', qty: 400, unit: 'g', cat: 'Proteins' }, { name: 'Garlic', qty: 6, unit: 'cloves', cat: 'Vegetables' }, { name: 'Lemon', qty: 1, unit: 'pcs', cat: 'Fruits' }, { name: 'Butter', qty: 2, unit: 'tbsp', cat: 'Dairy' }, { name: 'Black Pepper', qty: 1, unit: 'tsp', cat: 'Spices' }]);

add('012', 'Crispy Garlic Chicken Stir-Fry with Bell Peppers', 'Juicy chicken cubes flash-fried in a hot wok with crunchy capsicum, sliced onions, and savory soy garlic sauce.', 'Asian', 'Dinner', 'Non-Vegetarian', 'Easy', 10, 12, 3, 210, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=600&q=80', ['Stir Fry', 'Asian', 'High Protein', 'Quick'], [{ text: 'Cut boneless chicken into bite-sized cubes. Toss with salt, pepper, and 1 tsp cornstarch or flour.', time: 3 }, { text: 'Heat oil in a wok until smoking hot. Sear chicken pieces for 5 minutes until golden; remove and set aside.', time: 5 }, { text: 'In the same wok, toss sliced bell peppers, onions, and minced garlic on high heat for 3 minutes until crisp-tender.', time: 3 }, { text: 'Return chicken to pan, add soy sauce or seasonings, toss vigorously for 1 minute, and garnish with spring onions.', time: 1 }], { calories: 340, protein: 36, carbs: 12, fat: 16, fiber: 2.5 }, [{ name: 'Chicken', qty: 400, unit: 'g', cat: 'Proteins' }, { name: 'Bell Pepper', qty: 2, unit: 'pcs', cat: 'Vegetables' }, { name: 'Onion', qty: 1, unit: 'pcs', cat: 'Vegetables' }, { name: 'Garlic', qty: 5, unit: 'cloves', cat: 'Vegetables' }, { name: 'Cooking Oil', qty: 2, unit: 'tbsp', cat: 'Oils & Condiments' }]);

