add('014', 'Chicken Alfredo Penne Pasta', 'Al dente penne pasta and sliced seared chicken breast coated in a velvety garlic parmesan cream sauce.', 'Italian', 'Dinner', 'Non-Vegetarian', 'Medium', 10, 18, 3, 260, 'https://images.unsplash.com/photo-1621996346565-e3d5d6281691?auto=format&fit=crop&w=600&q=80', ['Pasta', 'Italian', 'Comfort Food', 'Creamy'], [{ text: 'Boil penne pasta in salted water for 10 minutes until al dente; drain and reserve half cup pasta water.', time: 10 }, { text: 'Season chicken breast with salt and pepper; sear in butter for 6 minutes per side until cooked, then slice into strips.', time: 8 }, { text: 'In same pan, sauté minced garlic in butter; pour in cream/milk and simmer gently until thickened.', time: 4 }, { text: 'Toss pasta and sliced chicken in the rich sauce with cheese and black pepper. Garnish with parsley.', time: 3 }], { calories: 560, protein: 38, carbs: 54, fat: 22, fiber: 3 }, [{ name: 'Chicken', qty: 300, unit: 'g', cat: 'Proteins' }, { name: 'Pasta', qty: 250, unit: 'g', cat: 'Grains' }, { name: 'Garlic', qty: 4, unit: 'cloves', cat: 'Vegetables' }, { name: 'Butter', qty: 2, unit: 'tbsp', cat: 'Dairy' }, { name: 'Milk', qty: 1, unit: 'cup', cat: 'Dairy' }, { name: 'Cheese', qty: 50, unit: 'g', cat: 'Dairy' }]);

