add('016', 'Chicken Fried Rice (Takeout Style)', 'Fragrant jasmine or basmati rice stir-fried in a blazing hot wok with tender chicken, scrambled egg, and scallions.', 'Asian', 'Dinner', 'Non-Vegetarian', 'Easy', 10, 10, 3, 175, 'https://images.unsplash.com/photo-1603133872878-684f208fb84b?auto=format&fit=crop&w=600&q=80', ['Fried Rice', 'Asian', 'One Pan', 'Takeout'], [{ text: 'Heat 1 tbsp oil in a wok on high flame. Cook diced chicken pieces for 4 minutes until golden; push to the side.', time: 4 }, { text: 'Crack egg directly into the wok and scramble softly.', time: 1 }, { text: 'Add chilled cooked rice, diced carrots, onions, and minced garlic.', time: 2 }, { text: 'Drizzle 2 tbsp soy sauce and pepper; toss on high flame for 3 minutes until aromatic and slightly smoky.', time: 3 }], { calories: 490, protein: 32, carbs: 62, fat: 12, fiber: 2.8 }, [{ name: 'Chicken', qty: 250, unit: 'g', cat: 'Proteins' }, { name: 'Rice', qty: 2, unit: 'cups', cat: 'Grains' }, { name: 'Egg', qty: 2, unit: 'pcs', cat: 'Proteins' }, { name: 'Onion', qty: 1, unit: 'pcs', cat: 'Vegetables' }, { name: 'Carrot', qty: 1, unit: 'pcs', cat: 'Vegetables' }, { name: 'Garlic', qty: 4, unit: 'cloves', cat: 'Vegetables' }]);

add('017', 'Honey Garlic Pan Chicken', 'Crispy pan-fried chicken bites coated in a sticky, sweet and savory honey garlic butter glaze.', 'Asian', 'Dinner', 'Non-Vegetarian', 'Easy', 8, 12, 2, 190, 'https://images.unsplash.com/photo-1527477321055-436158a2b00d?auto=format&fit=crop&w=600&q=80', ['Honey Garlic', 'Chicken', 'Quick Dinner', 'Sticky'], [{ text: 'Cut boneless chicken into bite-sized nuggets; season with salt and pepper.', time: 3 }, { text: 'Sear chicken in 1 tbsp oil over medium-high heat for 6 minutes until cooked and browned.', time: 6 }, { text: 'Reduce flame; add 1 tbsp butter, 6 minced garlic cloves, 3 tbsp honey, and 1 tbsp soy sauce.', time: 2 }, { text: 'Simmer glaze rapidly for 2 minutes until bubbling and caramelized around the chicken. Sprinkle sesame seeds.', time: 2 }], { calories: 370, protein: 34, carbs: 22, fat: 16, fiber: 0.5 }, [{ name: 'Chicken', qty: 350, unit: 'g', cat: 'Proteins' }, { name: 'Garlic', qty: 6, unit: 'cloves', cat: 'Vegetables' }, { name: 'Honey', qty: 3, unit: 'tbsp', cat: 'Pantry' }, { name: 'Butter', qty: 1, unit: 'tbsp', cat: 'Dairy' }]);

add('018', 'Classic Chicken Clear Soup', 'Nourishing comforting broth simmered with tender chicken, sliced carrots, crushed ginger, garlic, and cracked pepper.', 'Continental', 'Dinner', 'Non-Vegetarian', 'Easy', 8, 15, 3, 120, 'https://images.unsplash.com/photo-1547592166-23ac45744acd?auto=format&fit=crop&w=600&q=80', ['Soup', 'Comfort Food', 'Healthy', 'Chicken'], [{ text: 'In a soup pot, heat 1 tsp butter; add crushed ginger and garlic; sauté for 1 minute.', time: 2 }, { text: 'Add chicken pieces, sliced carrots, onions, and 4 cups water or broth.', time: 3 }, { text: 'Bring to boil; skim foam, then simmer on low heat for 12 minutes until chicken is tender.', time: 12 }, { text: 'Season with salt and lots of freshly crushed black pepper. Garnish with coriander and serve steaming hot.', time: 2 }], { calories: 180, protein: 26, carbs: 6, fat: 5, fiber: 1.5 }, [{ name: 'Chicken', qty: 300, unit: 'g', cat: 'Proteins' }, { name: 'Carrot', qty: 1, unit: 'pcs', cat: 'Vegetables' }, { name: 'Onion', qty: 1, unit: 'pcs', cat: 'Vegetables' }, { name: 'Ginger', qty: 1, unit: 'inch', cat: 'Vegetables' }, { name: 'Garlic', qty: 5, unit: 'cloves', cat: 'Vegetables' }, { name: 'Black Pepper', qty: 1, unit: 'tsp', cat: 'Spices' }]);

// 3. PANEER & VEGGIE DELIGHTS
add('019', 'Restaurant Style Paneer Butter Masala', 'Soft paneer cubes simmered in a silky, rich, mildly sweet tomato-butter gravy scented with kasuri methi.', 'Indian', 'Dinner', 'Vegetarian', 'Medium', 15, 20, 4, 180, 'https://images.unsplash.com/photo-1631452180519-c014fe946bc7?auto=format&fit=crop&w=600&q=80', ['Paneer', 'Restaurant Style', 'Rich', 'Vegetarian'], [{ text: 'Puree boiled ripe tomatoes with ginger, garlic, and cashews into a smooth silky paste.', time: 5 }, { text: 'Heat butter and oil in a pan; add whole spices, turmeric, and Kashmiri red chilli powder for vibrant color.', time: 2 }, { text: 'Pour in tomato puree; cook on medium flame for 10 minutes until thickened and oil floats on top.', time: 10 }, { text: 'Add fresh paneer cubes, cream, salt, and crushed kasuri methi. Simmer gently for 4 minutes.', time: 4 }], { calories: 430, protein: 16, carbs: 16, fat: 34, fiber: 3.5 }, [{ name: 'Paneer', qty: 300, unit: 'g', cat: 'Dairy' }, { name: 'Tomato', qty: 4, unit: 'pcs', cat: 'Vegetables' }, { name: 'Butter', qty: 3, unit: 'tbsp', cat: 'Dairy' }, { name: 'Milk', qty: 0.5, unit: 'cup', cat: 'Dairy' }, { name: 'Ginger', qty: 1, unit: 'inch', cat: 'Vegetables' }, { name: 'Garlic', qty: 6, unit: 'cloves', cat: 'Vegetables' }]);

add('020', 'Homestyle Paneer Bhurji', 'Crumbled fresh paneer sautéed with caramelized onions, tangy tomatoes, green chillies, and fragrant spices.', 'Indian', 'Dinner', 'Vegetarian', 'Easy', 8, 12, 2, 120, 'https://images.unsplash.com/photo-1565557623262-b51c2513a641?auto=format&fit=crop&w=600&q=80', ['Paneer', 'Quick 15m', 'High Protein', 'Vegetarian'], [{ text: 'Heat oil or butter in a pan. Splutter cumin seeds and sauté chopped onions and ginger-garlic until translucent.', time: 3 }, { text: 'Add chopped tomatoes, green chillies, turmeric, red chilli powder, and salt. Cook until mushy.', time: 4 }, { text: 'Crumble fresh paneer with your fingers and fold into the spiced tomato-onion masala.', time: 2 }, { text: 'Cook for just 3 minutes so paneer stays soft and moist. Garnish with chopped coriander and serve with roti.', time: 3 }], { calories: 340, protein: 20, carbs: 10, fat: 24, fiber: 2 }, [{ name: 'Paneer', qty: 250, unit: 'g', cat: 'Dairy' }, { name: 'Onion', qty: 2, unit: 'pcs', cat: 'Vegetables' }, { name: 'Tomato', qty: 2, unit: 'pcs', cat: 'Vegetables' }, { name: 'Green Chilli', qty: 2, unit: 'pcs', cat: 'Vegetables' }, { name: 'Coriander', qty: 2, unit: 'tbsp', cat: 'Vegetables' }, { name: 'Butter', qty: 1, unit: 'tbsp', cat: 'Dairy' }]);

add('021', 'Classic Palak Paneer (Spinach Cottage Cheese)', 'Fresh vibrant spinach blanched and pureed into a velvety spiced garlic gravy with tender golden-seared paneer cubes.', 'Indian', 'Dinner', 'Vegetarian', 'Medium', 12, 15, 3, 150, 'https://images.unsplash.com/photo-1589647363585-f4a7d3877b10?auto=format&fit=crop&w=600&q=80', ['Palak', 'Paneer', 'Iron Rich', 'North Indian'], [{ text: 'Blanch fresh spinach in boiling water for 2 minutes; immediately plunge into ice-cold water and blend to a smooth puree.', time: 4 }, { text: 'Heat oil in a pan; fry paneer cubes lightly for 2 minutes until pale golden and set aside.', time: 3 }, { text: 'In same pan, sauté cumin, lots of chopped garlic, onions, and green chillies until fragrant.', time: 4 }, { text: 'Add pureed spinach, salt, garam masala, and fried paneer cubes. Simmer for 4 minutes and finish with butter.', time: 4 }], { calories: 320, protein: 18, carbs: 12, fat: 22, fiber: 5.5 }, [{ name: 'Paneer', qty: 250, unit: 'g', cat: 'Dairy' }, { name: 'Spinach', qty: 300, unit: 'g', cat: 'Vegetables' }, { name: 'Garlic', qty: 8, unit: 'cloves', cat: 'Vegetables' }, { name: 'Onion', qty: 1, unit: 'pcs', cat: 'Vegetables' }, { name: 'Green Chilli', qty: 2, unit: 'pcs', cat: 'Vegetables' }, { name: 'Butter', qty: 1, unit: 'tbsp', cat: 'Dairy' }]);

add('022', 'Kadai Paneer with Bell Peppers & Onions', 'Paneer cubes and crunchy bell pepper petals tossed in a spicy, freshly pounded coriander-red chilli kadai masala.', 'Indian', 'Dinner', 'Vegetarian', 'Medium', 12, 15, 3, 160, 'https://images.unsplash.com/photo-1631452180519-c014fe946bc7?auto=format&fit=crop&w=600&q=80', ['Kadai', 'Paneer', 'Spicy', 'Restaurant Style'], [{ text: 'Dry roast coriander seeds and dry red chillies; grind coarsely into kadai masala.', time: 3 }, { text: 'Heat oil in a kadai; toss cubed capsicum and onion petals on high heat for 3 minutes until crisp-tender; set aside.', time: 3 }, { text: 'In same kadai, cook onion-tomato puree with ginger-garlic paste and kadai masala until fragrant.', time: 6 }, { text: 'Fold in paneer cubes and sautéed bell peppers. Simmer for 3 minutes and garnish with fresh ginger juliennes.', time: 3 }], { calories: 360, protein: 17, carbs: 14, fat: 26, fiber: 4 }, [{ name: 'Paneer', qty: 300, unit: 'g', cat: 'Dairy' }, { name: 'Bell Pepper', qty: 2, unit: 'pcs', cat: 'Vegetables' }, { name: 'Onion', qty: 2, unit: 'pcs', cat: 'Vegetables' }, { name: 'Tomato', qty: 2, unit: 'pcs', cat: 'Vegetables' }, { name: 'Ginger', qty: 1, unit: 'inch', cat: 'Vegetables' }, { name: 'Garlic', qty: 5, unit: 'cloves', cat: 'Vegetables' }]);

add('023', 'Crispy Chilli Paneer (Indo-Chinese Wok)', 'Golden batter-crisped paneer cubes tossed in a sizzling wok with dark soy, chilli sauce, diced bell peppers, and spring onions.', 'Asian', 'Dinner', 'Vegetarian', 'Medium', 12, 12, 3, 170, 'https://images.unsplash.com/photo-1565557623262-b51c2513a641?auto=format&fit=crop&w=600&q=80', ['Chilli Paneer', 'Indo-Chinese', 'Appetizer', 'Spicy'], [{ text: 'Cut paneer into cubes; coat in a light dusting of flour, cornstarch, salt, and black pepper.', time: 3 }, { text: 'Shallow fry paneer in 2 tbsp oil on high flame until crisp and golden on all sides; remove.', time: 4 }, { text: 'In same pan, flash-fry minced garlic, green chillies, onion cubes, and bell peppers on high heat for 2 minutes.', time: 2 }, { text: 'Add soy sauce, chilli sauce, vinegar, and 2 tbsp water. Toss fried paneer into the bubbling sauce for 1 minute.', time: 2 }], { calories: 380, protein: 18, carbs: 22, fat: 26, fiber: 2.5 }, [{ name: 'Paneer', qty: 250, unit: 'g', cat: 'Dairy' }, { name: 'Bell Pepper', qty: 1, unit: 'pcs', cat: 'Vegetables' }, { name: 'Onion', qty: 1, unit: 'pcs', cat: 'Vegetables' }, { name: 'Green Chilli', qty: 3, unit: 'pcs', cat: 'Vegetables' }, { name: 'Garlic', qty: 6, unit: 'cloves', cat: 'Vegetables' }, { name: 'Cooking Oil', qty: 2, unit: 'tbsp', cat: 'Oils & Condiments' }]);

// 4. MUSHROOM, POTATO & VEGETABLES
add('024', 'Garlic Butter Sautéed Mushrooms', 'Fresh sliced button mushrooms pan-roasted in foaming garlic herb butter until caramelized, juicy, and golden.', 'Continental', 'Dinner', 'Vegetarian', 'Easy', 5, 8, 2, 95, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=600&q=80', ['Mushrooms', 'Quick 10m', 'Keto', 'Side Dish'], [{ text: 'Wipe mushrooms clean with a damp towel and cut into thick slices.', time: 2 }, { text: 'Melt generous butter with 1 tsp oil in a wide skillet over medium-high heat.', time: 1 }, { text: 'Add mushrooms in a single layer without crowding; cook undisturbed for 4 minutes until deeply browned.', time: 4 }, { text: 'Flip, add minced garlic, black pepper, and salt. Sauté for 2 minutes and finish with fresh coriander.', time: 2 }], { calories: 160, protein: 5, carbs: 6, fat: 14, fiber: 2 }, [{ name: 'Mushroom', qty: 300, unit: 'g', cat: 'Vegetables' }, { name: 'Garlic', qty: 6, unit: 'cloves', cat: 'Vegetables' }, { name: 'Butter', qty: 2, unit: 'tbsp', cat: 'Dairy' }, { name: 'Black Pepper', qty: 1, unit: 'tsp', cat: 'Spices' }, { name: 'Coriander', qty: 1, unit: 'tbsp', cat: 'Vegetables' }]);

add('025', 'Cream of Mushroom Soup', 'Velvety comforting soup prepared with deeply browned mushrooms, sweet caramelized onions, garlic, and cream.', 'Continental', 'Dinner', 'Vegetarian', 'Easy', 10, 15, 3, 110, 'https://images.unsplash.com/photo-1547592166-23ac45744acd?auto=format&fit=crop&w=600&q=80', ['Soup', 'Mushroom', 'Creamy', 'Comfort Food'], [{ text: 'Slice mushrooms and dice onions and garlic.', time: 3 }, { text: 'Melt butter in a pot; sauté onions and garlic for 3 minutes, then add mushrooms and cook for 6 minutes until browned.', time: 6 }, { text: 'Pour in milk or water, black pepper, and salt. Simmer gently for 6 minutes.', time: 6 }, { text: 'Blend half of the soup for a thick creamy texture, return to pot, and serve hot with crusty bread.', time: 2 }], { calories: 210, protein: 6, carbs: 14, fat: 15, fiber: 2.5 }, [{ name: 'Mushroom', qty: 300, unit: 'g', cat: 'Vegetables' }, { name: 'Onion', qty: 1, unit: 'pcs', cat: 'Vegetables' }, { name: 'Garlic', qty: 4, unit: 'cloves', cat: 'Vegetables' }, { name: 'Butter', qty: 2, unit: 'tbsp', cat: 'Dairy' }, { name: 'Milk', qty: 1, unit: 'cup', cat: 'Dairy' }]);

add('026', 'Crispy Jeera Aloo (Cumin Spiced Potatoes)', 'Boiled potatoes cut into cubes and pan-roasted with abundant roasted cumin seeds, green chillies, and amchur.', 'Indian', 'Lunch', 'Vegetarian', 'Easy', 8, 10, 3, 45, 'https://images.unsplash.com/photo-1546833999-b9f581a1996d?auto=format&fit=crop&w=600&q=80', ['Quick 15m', 'Vegan', 'Potato', 'Gluten-Free'], [{ text: 'Boil potatoes until just tender; peel and cut into 1-inch uniform cubes.', time: 4 }, { text: 'Heat oil or ghee in a pan. Add 2 tsp cumin seeds and let them sizzle until fragrant and deeply browned.', time: 2 }, { text: 'Add slit green chillies, turmeric, red chilli powder, salt, and the potato cubes.', time: 2 }, { text: 'Toss on medium-high heat for 6-8 minutes until potatoes develop a golden crispy exterior. Sprinkle fresh coriander.', time: 6 }], { calories: 210, protein: 4, carbs: 36, fat: 6, fiber: 4 }, [{ name: 'Potato', qty: 4, unit: 'pcs', cat: 'Vegetables' }, { name: 'Green Chilli', qty: 3, unit: 'pcs', cat: 'Vegetables' }, { name: 'Coriander', qty: 2, unit: 'tbsp', cat: 'Vegetables' }, { name: 'Cooking Oil', qty: 2, unit: 'tbsp', cat: 'Oils & Condiments' }, { name: 'Cumin Seeds', qty: 2, unit: 'tsp', cat: 'Spices' }]);

add('027', 'Homestyle Aloo Gobi Matar (Potato, Cauliflower & Peas)', 'Classic North Indian everyday dry curry cooked with tender florets of cauliflower, diced potatoes, and sweet green peas.', 'Indian', 'Dinner', 'Vegetarian', 'Easy', 12, 18, 4, 80, 'https://images.unsplash.com/photo-1546833999-b9f581a1996d?auto=format&fit=crop&w=600&q=80', ['Vegan', 'Everyday', 'Curry', 'Homestyle'], [{ text: 'Chop cauliflower into small florets, peel and cube potatoes, and rinse green peas.', time: 5 }, { text: 'Heat oil in a kadai; splutter cumin seeds, sliced ginger, and green chillies.', time: 2 }, { text: 'Add potatoes and cauliflower; sauté on medium heat with turmeric and salt for 5 minutes.', time: 5 }, { text: 'Add green peas, chopped tomatoes, and garam masala. Cover and cook on low heat for 10 minutes until vegetables are tender.', time: 10 }], { calories: 190, protein: 6, carbs: 32, fat: 5, fiber: 6.5 }, [{ name: 'Potato', qty: 2, unit: 'pcs', cat: 'Vegetables' }, { name: 'Cauliflower', qty: 250, unit: 'g', cat: 'Vegetables' }, { name: 'Green Peas', qty: 0.5, unit: 'cup', cat: 'Vegetables' }, { name: 'Tomato', qty: 1, unit: 'pcs', cat: 'Vegetables' }, { name: 'Ginger', qty: 1, unit: 'inch', cat: 'Vegetables' }, { name: 'Green Chilli', qty: 2, unit: 'pcs', cat: 'Vegetables' }]);

add('028', 'Crispy Garlic Potato Wedges', 'Oven-baked or pan-crisped potato wedges tossed in olive oil, crushed garlic, rosemary, paprika, and sea salt.', 'Continental', 'Snack', 'Vegetarian', 'Easy', 8, 20, 3, 50, 'https://images.unsplash.com/photo-1573080496219-bb080dd4f877?auto=format&fit=crop&w=600&q=80', ['Snack', 'Crispy', 'Potato', 'Appetizer'], [{ text: 'Scrub potatoes clean, cut lengthwise into wedges, and parboil in salted water for 5 minutes; drain thoroughly.', time: 7 }, { text: 'Toss wedges in olive oil, minced garlic, paprika, black pepper, and salt until evenly coated.', time: 2 }, { text: 'Bake at 200°C (400°F) for 25 minutes or pan-fry in a shallow skillet on medium heat for 15 minutes, flipping once.', time: 18 }, { text: 'Serve steaming hot with ketchup, garlic mayo, or mint dip.', time: 1 }], { calories: 230, protein: 4, carbs: 38, fat: 8, fiber: 4.5 }, [{ name: 'Potato', qty: 4, unit: 'pcs', cat: 'Vegetables' }, { name: 'Garlic', qty: 5, unit: 'cloves', cat: 'Vegetables' }, { name: 'Cooking Oil', qty: 2, unit: 'tbsp', cat: 'Oils & Condiments' }, { name: 'Black Pepper', qty: 1, unit: 'tsp', cat: 'Spices' }]);

add('029', 'Homestyle Bhindi Masala (Crispy Spiced Okra)', 'Tender fresh okra sliced and pan-fried until non-sticky, tossed with onions, mango powder (amchur), and dry spices.', 'Indian', 'Lunch', 'Vegetarian', 'Easy', 10, 15, 3, 60, 'https://images.unsplash.com/photo-1546833999-b9f581a1996d?auto=format&fit=crop&w=600&q=80', ['Bhindi', 'Okra', 'Vegan', 'Dry Curry'], [{ text: 'Wash bhindi and dry completely with a clean cloth before chopping into 1-inch pieces to prevent stickiness.', time: 5 }, { text: 'Heat oil in a wide pan; fry bhindi on medium flame for 8 minutes until crisp and no longer slimy; remove.', time: 8 }, { text: 'In same pan, sauté sliced onions and green chillies until golden brown.', time: 3 }, { text: 'Add turmeric, red chilli powder, coriander powder, salt, and the fried bhindi. Toss on medium heat for 4 minutes.', time: 4 }], { calories: 150, protein: 3.5, carbs: 16, fat: 8, fiber: 5 }, [{ name: 'Okra', qty: 350, unit: 'g', cat: 'Vegetables' }, { name: 'Onion', qty: 2, unit: 'pcs', cat: 'Vegetables' }, { name: 'Green Chilli', qty: 2, unit: 'pcs', cat: 'Vegetables' }, { name: 'Cooking Oil', qty: 2, unit: 'tbsp', cat: 'Oils & Condiments' }]);

// 5. OATS, BREAKFAST & FRUITS
add('030', 'Warm Cinnamon Apple & Honey Oatmeal Bowl', 'Rolled oats simmered in creamy milk, topped with tender pan-cooked diced apples, cinnamon spice, and pure golden honey.', 'Continental', 'Breakfast', 'Vegetarian', 'Easy', 5, 8, 2, 70, 'https://images.unsplash.com/photo-1517673132405-a56a62b18caf?auto=format&fit=crop&w=600&q=80', ['Oats', 'Breakfast', 'Healthy', 'Apple'], [{ text: 'Dice fresh apple into bite-sized cubes.', time: 2 }, { text: 'In a small pan, cook apple cubes with a dash of water, cinnamon, and 1 tsp honey for 3 minutes until tender.', time: 3 }, { text: 'In another pot, bring oats and milk (or water) to a gentle simmer for 4 minutes until thick and creamy.', time: 4 }, { text: 'Pour warm oatmeal into a bowl, top with cinnamon-cooked apples, and drizzle generous raw honey.', time: 1 }], { calories: 320, protein: 11, carbs: 58, fat: 6, fiber: 7 }, [{ name: 'Oats', qty: 1, unit: 'cup', cat: 'Grains' }, { name: 'Apple', qty: 1, unit: 'pcs', cat: 'Fruits' }, { name: 'Milk', qty: 1.5, unit: 'cups', cat: 'Dairy' }, { name: 'Honey', qty: 2, unit: 'tbsp', cat: 'Pantry' }]);

add('031', 'Baked Apple Cinnamon Oat Crisp', 'Sweet tender baked apples layered under a golden crispy crumble of rolled oats, honey, butter, and cinnamon.', 'Continental', 'Dessert', 'Vegetarian', 'Easy', 8, 15, 2, 85, 'https://images.unsplash.com/photo-1517673132405-a56a62b18caf?auto=format&fit=crop&w=600&q=80', ['Apple', 'Oats', 'Baked', 'Healthy Dessert'], [{ text: 'Thinly slice apples and toss in a baking dish with 1 tbsp honey and cinnamon.', time: 3 }, { text: 'In a bowl, mix rolled oats with softened butter and 1 tbsp honey into coarse crumbles.', time: 2 }, { text: 'Spread the oat crumble evenly over the apples.', time: 1 }, { text: 'Bake at 190°C (375°F) for 15 minutes or cook on stovetop in a covered buttered skillet until apples soften and crumble is golden.', time: 15 }], { calories: 280, protein: 6, carbs: 52, fat: 8, fiber: 6 }, [{ name: 'Apple', qty: 2, unit: 'pcs', cat: 'Fruits' }, { name: 'Oats', qty: 1, unit: 'cup', cat: 'Grains' }, { name: 'Honey', qty: 2, unit: 'tbsp', cat: 'Pantry' }, { name: 'Butter', qty: 1.5, unit: 'tbsp', cat: 'Dairy' }]);

add('032', 'Apple Honey Overnight Oats Smoothie', 'Velvety chilled smoothie made by blending soaked oats with crisp sweet apples, chilled milk, and honey.', 'American', 'Breakfast', 'Vegetarian', 'Easy', 4, 1, 2, 65, 'https://images.unsplash.com/photo-1553530666-ba11a7da3888?auto=format&fit=crop&w=600&q=80', ['Smoothie', 'Oats', 'Apple', 'No Cook'], [{ text: 'Core and chop sweet apple into chunks.', time: 1 }, { text: 'Add rolled oats, apple chunks, chilled milk, and honey into a blender.', time: 1 }, { text: 'Blend on high speed for 90 seconds until completely silky and smooth.', time: 2 }, { text: 'Pour into glasses and sprinkle a pinch of ground cinnamon on top.', time: 1 }], { calories: 290, protein: 9, carbs: 54, fat: 4.5, fiber: 5 }, [{ name: 'Apple', qty: 1, unit: 'pcs', cat: 'Fruits' }, { name: 'Oats', qty: 0.5, unit: 'cup', cat: 'Grains' }, { name: 'Milk', qty: 1, unit: 'cup', cat: 'Dairy' }, { name: 'Honey', qty: 1.5, unit: 'tbsp', cat: 'Pantry' }]);

add('033', 'Peanut Butter Banana Smoothie Bowl', 'Thick and creamy blend of ripe bananas, creamy peanut butter, milk, and honey, topped with fruit and nuts.', 'American', 'Breakfast', 'Vegetarian', 'Easy', 5, 2, 2, 85, 'https://images.unsplash.com/photo-1553530666-ba11a7da3888?auto=format&fit=crop&w=600&q=80', ['Smoothie', 'Banana', 'High Protein', 'Post Workout'], [{ text: 'Peel ripe bananas and break into pieces into a high-speed blender.', time: 1 }, { text: 'Add creamy peanut butter, chilled milk, and 1 tbsp honey.', time: 1 }, { text: 'Blend on high speed for 60-90 seconds until completely thick, creamy, and velvety.', time: 2 }, { text: 'Pour into chilled glasses or a bowl; garnish with extra banana slices and a sprinkle of nuts.', time: 1 }], { calories: 380, protein: 14, carbs: 52, fat: 15, fiber: 6 }, [{ name: 'Banana', qty: 2, unit: 'pcs', cat: 'Fruits' }, { name: 'Peanuts', qty: 2, unit: 'tbsp', cat: 'Grains' }, { name: 'Milk', qty: 1, unit: 'cup', cat: 'Dairy' }, { name: 'Honey', qty: 1, unit: 'tbsp', cat: 'Pantry' }]);

add('034', 'Classic Golden Fluffy Pancakes', 'Melt-in-your-mouth fluffy homemade pancakes prepared with flour, milk, egg, butter, and served with honey or syrup.', 'American', 'Breakfast', 'Eggetarian', 'Easy', 7, 10, 3, 80, 'https://images.unsplash.com/photo-1528207776546-365bb710ee93?auto=format&fit=crop&w=600&q=80', ['Pancakes', 'Breakfast', 'Weekend Brunch', 'Kids Favorite'], [{ text: 'Whisk flour, 1 tsp baking powder, a pinch of salt, and 1 tbsp sugar in a bowl.', time: 2 }, { text: 'In separate bowl, whisk milk, egg, and melted butter. Fold into dry ingredients until just combined.', time: 3 }, { text: 'Heat a non-stick griddle over medium heat and lightly butter. Pour 1/4 cup batter for each pancake.', time: 2 }, { text: 'Cook until bubbles form on surface (about 2.5 minutes), flip, and cook 2 minutes more until golden. Serve with honey or butter.', time: 4 }], { calories: 290, protein: 9, carbs: 42, fat: 10, fiber: 1.5 }, [{ name: 'Flour', qty: 1.5, unit: 'cups', cat: 'Grains' }, { name: 'Milk', qty: 1, unit: 'cup', cat: 'Dairy' }, { name: 'Egg', qty: 1, unit: 'pcs', cat: 'Proteins' }, { name: 'Butter', qty: 2, unit: 'tbsp', cat: 'Dairy' }, { name: 'Honey', qty: 2, unit: 'tbsp', cat: 'Pantry' }]);

// 6. PASTA, NOODLES & ITALIAN
add('035', 'Spaghetti Aglio e Olio with Garlic & Chilli', 'Classic traditional Roman pasta tossed in extra virgin olive oil, sizzling golden garlic slivers, and fiery red chilli flakes.', 'Italian', 'Dinner', 'Vegetarian', 'Easy', 5, 12, 2, 110, 'https://images.unsplash.com/photo-1551183053-bf91a1d81141?auto=format&fit=crop&w=600&q=80', ['Pasta', 'Classic Italian', 'Quick 15m', 'Vegan Option'], [{ text: 'Boil spaghetti in generously salted water until al dente (about 9-10 minutes); reserve 1/2 cup pasta cooking water.', time: 10 }, { text: 'In a wide skillet, heat 3 tbsp olive oil over low-medium heat. Add thinly sliced garlic and sauté gently until pale golden.', time: 3 }, { text: 'Add red chilli flakes or sliced green chillies and cook for 30 seconds.', time: 1 }, { text: 'Transfer drained spaghetti to the skillet with a splash of reserved pasta water. Toss vigorously for 2 minutes until glossy; top with parsley.', time: 2 }], { calories: 410, protein: 12, carbs: 64, fat: 14, fiber: 3 }, [{ name: 'Pasta', qty: 250, unit: 'g', cat: 'Grains' }, { name: 'Garlic', qty: 8, unit: 'cloves', cat: 'Vegetables' }, { name: 'Cooking Oil', qty: 3, unit: 'tbsp', cat: 'Oils & Condiments' }, { name: 'Red Chilli Powder', qty: 1, unit: 'tsp', cat: 'Spices' }, { name: 'Coriander', qty: 2, unit: 'tbsp', cat: 'Vegetables' }]);

add('036', 'Penne all\'Arrabbiata (Spicy Tomato Garlic Pasta)', 'Tube penne pasta coated in a fiery, rich Italian sauce made from ripe tomatoes, crushed garlic, and red chillies.', 'Italian', 'Dinner', 'Vegetarian', 'Easy', 8, 15, 3, 120, 'https://images.unsplash.com/photo-1621996346565-e3d5d6281691?auto=format&fit=crop&w=600&q=80', ['Pasta', 'Spicy', 'Italian', 'Vegetarian'], [{ text: 'Boil penne pasta in rolling salted water for 10 minutes until al dente; drain and save 1/2 cup pasta water.', time: 10 }, { text: 'Heat olive oil in a skillet; sauté lots of minced garlic and red chillies on medium flame until fragrant.', time: 3 }, { text: 'Add crushed ripe tomatoes or puree, salt, and black pepper. Simmer on low heat for 10 minutes until thick and rich.', time: 10 }, { text: 'Fold in boiled penne with a splash of pasta water. Toss vigorously for 2 minutes to emulsify sauce. Top with cheese.', time: 2 }], { calories: 370, protein: 13, carbs: 66, fat: 8, fiber: 4.5 }, [{ name: 'Pasta', qty: 250, unit: 'g', cat: 'Grains' }, { name: 'Tomato', qty: 4, unit: 'pcs', cat: 'Vegetables' }, { name: 'Garlic', qty: 6, unit: 'cloves', cat: 'Vegetables' }, { name: 'Cooking Oil', qty: 2, unit: 'tbsp', cat: 'Oils & Condiments' }, { name: 'Cheese', qty: 30, unit: 'g', cat: 'Dairy' }]);

add('037', 'Street Style Vegetable Hakka Noodles', 'Springy noodles flash-fried in a fiery wok with shredded cabbage, carrots, bell peppers, soy sauce, and chilli garlic.', 'Asian', 'Dinner', 'Vegetarian', 'Easy', 10, 10, 3, 90, 'https://images.unsplash.com/photo-1585032226651-759b368d7246?auto=format&fit=crop&w=600&q=80', ['Noodles', 'Indo-Chinese', 'Quick', 'Street Food'], [{ text: 'Boil noodles until 90% cooked (about 4 minutes); rinse under cold water, toss with 1 tsp oil to prevent sticking.', time: 5 }, { text: 'Heat oil in a large wok over highest heat until smoking.', time: 2 }, { text: 'Toss in sliced onions, minced garlic, carrots, and bell peppers. Stir fry continuously for 2.5 minutes so veggies stay crunchy.', time: 3 }, { text: 'Add boiled noodles, 2 tbsp soy sauce, vinegar or lemon, salt, and black pepper. Toss vigorously on high flame for 2 minutes.', time: 2 }], { calories: 360, protein: 9, carbs: 64, fat: 9, fiber: 4 }, [{ name: 'Noodles', qty: 200, unit: 'g', cat: 'Grains' }, { name: 'Carrot', qty: 1, unit: 'pcs', cat: 'Vegetables' }, { name: 'Bell Pepper', qty: 1, unit: 'pcs', cat: 'Vegetables' }, { name: 'Onion', qty: 1, unit: 'pcs', cat: 'Vegetables' }, { name: 'Garlic', qty: 5, unit: 'cloves', cat: 'Vegetables' }, { name: 'Cooking Oil', qty: 2, unit: 'tbsp', cat: 'Oils & Condiments' }]);

